import itertools
from pysat.solvers import Glucose3

def find_graph_with_cycle(n=8, girth=6):
    edges = {}
    var_to_edge = {}
    counter = 1
    for i in range(n):
        for j in range(i+1, n):
            edges[(i,j)] = counter
            var_to_edge[counter] = (i,j)
            counter += 1

    solver = Glucose3()

    def forbid_all(edge_list):
        return [-edges[e] for e in edge_list]

    clauses = []

    # Triangles
    for i,j,k in itertools.combinations(range(n), 3):
        e1 = (i,j) if i<j else (j,i)
        e2 = (i,k) if i<k else (k,i)
        e3 = (j,k) if j<k else (k,j)
        clauses.append(forbid_all([e1,e2,e3]))

    # 4-cycles
    for quad in itertools.combinations(range(n), 4):
        a,b,c,d = quad
        cycles = [
            [(a,b), (b,c), (c,d), (a,d)],
            [(a,b), (b,d), (c,d), (a,c)],
            [(a,c), (b,c), (b,d), (a,d)]
        ]
        for cyc in cycles:
            ordered = []
            for (x,y) in cyc:
                if x<y:
                    ordered.append((x,y))
                else:
                    ordered.append((y,x))
            clauses.append(forbid_all(ordered))

    # 5-cycles
    for pent in itertools.combinations(range(n), 5):
        seen = set()
        for perm in itertools.permutations(pent):
            edges_set = frozenset([(perm[i], perm[(i+1)%5]) if perm[i] < perm[(i+1)%5] else (perm[(i+1)%5], perm[i]) for i in range(5)])
            if edges_set not in seen:
                seen.add(edges_set)
                clauses.append([-edges[e] for e in edges_set])

    # Enforce at least one edge (to avoid empty graph)
    # At least one edge true: clause with all positive literals
    clauses.append([edges[e] for e in edges])

    # Also enforce that there is at least one cycle: we can require that the graph has at least n edges (since tree has n-1)
    # But that's not necessary; we can just require a specific 6-cycle.
    # Let's try to enforce a 6-cycle: 0-1-2-3-4-5-0
    cycle_edges = [(0,1),(1,2),(2,3),(3,4),(4,5),(0,5)]
    for e in cycle_edges:
        if e[0] > e[1]:
            e = (e[1], e[0])
        clauses.append([edges[e]])  # each edge must be true

    print(f"Number of clauses: {len(clauses)}")

    for cl in clauses:
        solver.add_clause(cl)

    if solver.solve():
        model = solver.get_model()
        edge_list = []
        for var, val in enumerate(model, start=1):
            if val > 0 and var in var_to_edge:
                edge_list.append(var_to_edge[var])
        return edge_list
    else:
        return None

