    from collections import deque
    def shortest_cycle():
        best = float('inf')
        for start in range(8):
            # BFS from start, track parent and distance
            parent = [-1]*8
            dist = [-1]*8
            q = deque([start])
            dist[start] = 0
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        q.append(v)
                    elif v != parent[u] and parent[v] != u:
                        # found cycle
                        cycle_len = dist[u] + dist[v] + 1
                        if cycle_len < best:
                            best = cycle_len
        return best
    print("Shortest cycle:", shortest_cycle())
